#!/usr/bin/env ruby
# frozen_string_literal: true

require 'json'
require 'optparse'
require 'fileutils'

options = { input: nil, output: nil }
OptionParser.new do |parser|
  parser.banner = 'Usage: build_demo_html.rb --input RESULTS_JSON --output DEMO_HTML'
  parser.on('--input PATH', 'Simulation summary JSON') { |value| options[:input] = value }
  parser.on('--output PATH', 'Self-contained HTML demo') { |value| options[:output] = value }
end.parse!
abort 'Missing --input PATH' unless options[:input]
abort 'Missing --output PATH' unless options[:output]

data = JSON.parse(File.read(options[:input]))
FileUtils.mkdir_p(File.dirname(File.expand_path(options[:output])))
json = JSON.generate(data).gsub('</', '<\\/')
html = <<~HTML
  <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>RetailFlex Decision Sandbox</title>
  <style>
  body{font:16px/1.45 system-ui,sans-serif;margin:0;background:#f5f7f8;color:#13222e}.wrap{max-width:1160px;margin:auto;padding:32px}h1{margin:0;font-size:2.25rem}.kicker{color:#186445;font-weight:700;letter-spacing:.07em;text-transform:uppercase}.boundary{background:#fff4d6;border-left:5px solid #c57b00;padding:14px 18px;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.card,.panel{background:white;border:1px solid #dde3e7;border-radius:10px;padding:18px}.metric{font-size:1.75rem;font-weight:750}.muted{color:#546470}.risk{color:#9d3512;font-weight:700}table{border-collapse:collapse;width:100%;background:#fff}th,td{padding:10px;text-align:left;border-bottom:1px solid #e4e8eb}th{background:#eaf2ef}svg{width:100%;height:300px;background:white;border:1px solid #dde3e7;border-radius:10px}button{background:#186445;color:white;border:0;border-radius:6px;padding:9px 12px;margin:4px;cursor:pointer}button.active{background:#0e3e2a}.footer{font-size:.9rem;color:#53616d;margin-top:28px}
  </style><body><main class="wrap"><div class="kicker">University of Arkansas · NED³ · screening demonstration</div><h1>RetailFlex Decision Sandbox</h1><p class="muted">Representative Northwest Arkansas SuperMarket prototype · annual EnergyPlus simulations</p><div class="boundary" id="boundary"></div><section class="grid" id="cards"></section><h2>Illustrative peak-day comparison</h2><p class="muted">Selected summer event day: <strong id="day"></strong>; modeled event window: <strong id="window"></strong>. Lines show hourly facility electricity; one hourly kWh is presented as average kW.</p><div id="buttons"></div><svg id="chart" viewBox="0 0 1000 300" role="img" aria-label="Hourly facility electricity chart"></svg><section class="panel"><h2>What this demonstrates</h2><p>RetailFlex makes the intervention, model, and tradeoffs inspectable before a store-specific pilot. In this prototype, the thermal-shift case does not improve the selected event-window energy, so it is marked for rejection or redesign—not promoted as savings.</p><table><thead><tr><th>Case</th><th>Annual site electricity</th><th>Annual peak</th><th>Event-window energy</th><th>Screening interpretation</th></tr></thead><tbody id="table"></tbody></table></section><section class="grid" style="margin-top:16px"><div class="panel"><h2>What we need for a real-store assessment</h2><ul><li>Store format, floor area, major HVAC/refrigeration configuration</li><li>12 months of interval whole-building electricity and applicable tariff</li><li>Operating schedules and constraints</li><li>Read-only BMS point list/historical extract if approved</li></ul></div><div class="panel"><h2>Requested next decision</h2><p>Approve a data-and-operations scoping meeting for a read-only, limited store assessment. No live control, customer data, associate data, or fleet-wide dataset is requested.</p></div></section><p class="footer">Generated locally from versioned model scenarios. This page contains simulated prototype outputs only; it is not a Walmart analysis, operating instruction, safety assessment, or savings guarantee.</p></main><script>const d=#{json};const s=Object.values(d.summaries),base=d.summaries.baseline;const f=n=>n.toLocaleString(undefined,{maximumFractionDigits:0});document.querySelector('#boundary').textContent=d.claim_boundary;document.querySelector('#day').textContent=d.event_day;document.querySelector('#window').textContent=d.event_window;document.querySelector('#cards').innerHTML=`<div class="card"><div class="muted">Model status</div><div class="metric">Screening only</div></div><div class="card"><div class="muted">Baseline annual electricity</div><div class="metric">${f(base.annual_site_kwh)} kWh</div></div><div class="card"><div class="muted">Baseline annual peak</div><div class="metric">${f(base.annual_peak_kw)} kW</div></div><div class="card"><div class="muted">Primary decision</div><div class="metric">Pilot data scope</div></div>`;function verdict(x){if(x.id==='baseline')return 'Reference case';return x.event_window_kwh<base.event_window_kwh?'Candidate for further review':'Reject or redesign before pilot'}document.querySelector('#table').innerHTML=s.map(x=>`<tr><td><strong>${x.label}</strong><br><span class="muted">${x.description}</span></td><td>${f(x.annual_site_kwh)} kWh</td><td>${f(x.annual_peak_kw)} kW</td><td>${f(x.event_window_kwh)} kWh</td><td class="${verdict(x).startsWith('Reject')?'risk':''}">${verdict(x)}</td></tr>`).join('');const colors=['#186445','#1677b8','#cc6c1d'];let shown=s.map(x=>x.id);function draw(){document.querySelector('#buttons').innerHTML=s.map((x,i)=>`<button class="${shown.includes(x.id)?'active':''}" onclick="toggle('${x.id}')">${x.label}</button>`).join('');const all=s.flatMap(x=>x.event_day_hourly_kw.map(p=>p.kw)),max=Math.ceil(Math.max(...all)/20)*20,svg=document.querySelector('#chart');let out='';for(let y=0;y<=max;y+=max/4){let py=260-y/max*220;out+=`<line x1="55" y1="${py}" x2="970" y2="${py}" stroke="#dfe5e8"/><text x="5" y="${py+4}" font-size="12">${Math.round(y)} kW</text>`}for(let h=0;h<24;h+=3){let x=55+h/23*915;out+=`<text x="${x-8}" y="285" font-size="12">${h}:00</text>`}s.forEach((x,i)=>{if(!shown.includes(x.id))return;let pts=x.event_day_hourly_kw.map(p=>`${55+p.hour/23*915},${260-p.kw/max*220}`).join(' ');out+=`<polyline points="${pts}" fill="none" stroke="${colors[i]}" stroke-width="3"/><text x="${700}" y="${25+i*20}" fill="${colors[i]}" font-size="13">${x.label}</text>`});svg.innerHTML=out}window.toggle=id=>{shown=shown.includes(id)?shown.filter(x=>x!==id):[...shown,id];draw()};draw();</script></body></html>
HTML
File.write(options[:output], html)
puts "Wrote #{options[:output]}"
